333: // Index 0 = Red level, 1 = Amber level, 2 = Orange level
334: const CHOICE_THRESHOLDS: Record<string, [number, number, number]> = {
335:   Cognitive: [1.8, 2.2, 2.8],
336:   Emotional: [2, 2.5, 3],
337:   Moral: [2, 2.5, 3],
