350: async function runQuickCalibration(): Promise<Record<Line, Stage>> {
351:   const altitudes: Partial<Record<Line, Stage>> = {};
352:   const lines: Line[] = ['Cognitive', 'Emotional', 'Moral', 'Intrapersonal', 'Spiritual', 'Somatic', 'Willpower', 'Interpersonal'];
353: 
354:   banner('Quick Calibration');
355:   console.log(`  ${chalk.dim('A brief probe of each developmental line to set your starting altitudes.')}\n`);
356: 
357:   for (const line of lines) {
358:     let stage: Stage = 'Red';
359:     let confidence = 0.5;
360:     let trial: TrialResult;
361: 
362:     if (line === 'Somatic' || line === 'Willpower') {
363:       // ── Hold probe: measure timing accuracy ──
364:       const target = HOLD_TARGETS[line]!;
365:       const targetSec = (target / 1000).toFixed(1);
366: 
367:       console.log(`  ${chalk.bold.cyan(line + ':')} ${chalk.dim('Timing probe')}`);
368:       console.log(`  ${chalk.dim('Press Enter when you think ' + targetSec + ' seconds have passed.')}\n`);
369: 
370:       const startTime = Date.now();
371:       const answer = await clackText({ message: `Press Enter after ~${targetSec}s...`, defaultValue: '' });
372:       if (typeof answer === 'symbol') { altitudes[line] = 'Red'; continue; }
373:       const elapsed = Date.now() - startTime;
374: 
375:       const accuracy = Math.max(0, 1 - Math.abs(elapsed - target) / target);
376: 
377:       let threshold: number;
378:       if (line === 'Somatic') {
379:         // Inverted: lower RT = higher stage (range 200-900)
380:         threshold = 900 - accuracy * 700;
381:       } else {
382:         // Standard: higher = better (range 1-12)
383:         threshold = 1 + accuracy * 11;
384:       }
385: 
386:       stage = thresholdToStage(line, threshold);
387: 
388:       trial = {
389:         taskId: `cal-${line.toLowerCase()}`,
390:         timestamp: Date.now(),
391:         dimensions: { accuracy, response_time: accuracy },
392:         rawResponse: elapsed,
393:         durationMs: elapsed,
394:       };
395: 
396:       confidence = computeConfidence([trial], 0.5);
397: 
398:     } else {
399:       // ── LLM dialogue probe: multiple choice ──
400:       const probe = CALIBRATION_PROMPTS[line];
401:       if (!probe) { altitudes[line] = 'Red'; continue; }
402: 
403:       console.log(`  ${chalk.bold.cyan(line + ':')}`);
404:       console.log(`  ${chalk.dim(probe.prompt)}\n`);
405: 
406:       const choice = await select({
407:         message: `How would you approach this?`,
408:         options: probe.options.map((opt) => ({ value: opt, label: opt })),
409:       });
410: 
411:       if (typeof choice === 'symbol') { altitudes[line] = 'Red'; continue; }
412: 
413:       const choiceIdx = probe.options.indexOf(choice as string);
414:       const idx = choiceIdx >= 0 ? choiceIdx : 0;
415: 
416:       const thresholds = CHOICE_THRESHOLDS[line]!;
417:       const threshold = thresholds[Math.min(idx, 2)];
418: 
419:       stage = thresholdToStage(line, threshold);
420: 
421:       const depthScores = [0.3, 0.6, 0.85];
422:       const coherenceScores = [0.4, 0.7, 0.9];
423: 
424:       trial = {
425:         taskId: `cal-${line.toLowerCase()}`,
426:         timestamp: Date.now(),
427:         dimensions: { depth: depthScores[idx], coherence: coherenceScores[idx] },
428:         rawResponse: idx,
429:         durationMs: 0,
430:       };
431: 
432:       confidence = computeConfidence([trial], 0.5);
433:     }
434: 
435:     altitudes[line] = stage;
436: 
437:     const stageIdx = CAL_STAGES.indexOf(stage as typeof CAL_STAGES[number]);
438:     const color = stageColor(stage);
439:     const bar = '■'.repeat(stageIdx + 1) + '○'.repeat(7 - stageIdx);
440:     console.log(`  ${line.padEnd(14)} ${bar} ${color(stage)} ${chalk.dim('(confidence: ' + confidence.toFixed(2) + ')')}\n`);
441:   }
442: 
443:   console.log(`\n  ${chalk.bold('Calibration complete:')}`);
444:   for (const line of lines) {
445:     const s = altitudes[line] ?? 'Red';
446:     const color = stageColor(s);
447:     console.log(`    ${line.padEnd(14)} ${color(s)}`);
448:   }
449:   console.log('');
450: 
451:   return altitudes as Record<Line, Stage>;
452: }
