549: /** Render an altitude bar chart showing per-line stage progression */
550: function renderAltitudesChart(sig: Significator): void {
551:   const orderedLines: Line[] = ['Cognitive', 'Emotional', 'Moral', 'Intrapersonal', 'Spiritual', 'Somatic', 'Willpower', 'Interpersonal'];
552:   const allStages = ['Infrared', 'Magenta', 'Red', 'Amber', 'Orange', 'Green', 'Turquoise', 'White'] as const;
553:   const stageKeys: readonly string[] = allStages;
554: 
555:   for (const line of orderedLines) {
556:     const current = sig.altitudes[line] ?? 'Red';
557:     const currentIdx = stageKeys.indexOf(current);
558:     const color = stageColor(current);
559: 
560:     // Build a horizontal bar: filled squares up to current stage, empty beyond
561:     const bars = stageKeys.map((s, i) => {
562:       if (i < currentIdx) return chalk.dim('■');  // passed stages
563:       if (i === currentIdx) return color('●'); // current stage
564:       return chalk.dim('○'); // future stages
565:     });
566: 
567:     // Segment label: first 3 stages, current, last 2
568:     const segLabels = stageKeys.map((s, i) => {
569:       if (i === 0 || i === stageKeys.length - 1 || i === currentIdx) {
570:         return i === currentIdx ? color(stageAbbr(s)) : chalk.dim(stageAbbr(s));
571:       }
572:       return '  '; // skip most labels for compactness
573:     });
574: 
575:     // Pad line name to 15 chars for alignment
576:     const paddedLine = line.padEnd(14);
577:     if (!JSON_MODE) {
578:       console.log(`  ${paddedLine} ${bars.join('')} ${chalk.dim(current)}`);
579:     }
580:   }
581: }
