703: // ── AgenticOrchestrator encounter handler (all modalities) ────────────
704: async function runAgenticEncounter(
705:   encounter: ScheduledEncounter,
706:   sig: Significator,
707:   world: WorldState,
708:   history: ConsequenceRecord[],
709:   responsesPool?: number[],
710:   consecutivePasses?: Map<string, number>,
711: ): Promise<{
712:   outcome: import('../src/core/assessments/AgenticOrchestrator.js').OrchestratorResult;
713:   response: PlayerResponse;
714:   narrativeSummary: string;
715: }> {
716:   const [encLine, encStage] = encounter.moduleRef.split(':') as [Line, Stage];
717:   const modRegistry = (globalThis as any).__moduleRegistry as ModuleRegistry | undefined;
718: 
719:   // If --line/--stage/--modality forcing is active, override the encounter
720:   let forcedEncounter = encounter;
721:   if (FORCE_LINE || FORCE_STAGE || FORCE_MODALITY) {
722:     const forcedLine = FORCE_LINE ?? encLine;
723:     const forcedStage = FORCE_STAGE ?? encStage;
724:     const forcedModality = FORCE_MODALITY ?? encounter.modality;
725:     const forcedModule = modRegistry?.get(forcedLine, forcedStage);
726:     if (forcedModule) {
727:       forcedEncounter = {
728:         ...encounter,
729:         moduleRef: `${forcedLine}:${forcedStage}`,
730:         modality: forcedModality,
731:         targetLines: [forcedLine],
732:         stage: forcedStage,
733:       };
734:     }
735:   }
736: 
737:   const uiHandler: AgenticUIHandler = {
738:     askUser: async (params: AskUserQuestionParams): Promise<AskUserQuestionResult> => {
739:       const answers: UserAnswer[] = [];
740: 
741:       for (const q of params.questions) {
742:         if (!JSON_MODE) {
743:           const mod = forcedEncounter.modality;
744:           let modHeader = '';
745: 
746:           switch (mod) {
747:             case 'Deterministic':
748:               modHeader = `${chalk.bold.red('⏳ [TIMED TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)')}\n`;
749:               break;
750:             case 'LanguageReflective':
751:               modHeader = `${chalk.bold.blue('🧘 [REFLECTION BEAT] • Tune in to your inner state •')}\n`;
752:               break;
753:             case 'ScenarioChoice':
754:               modHeader = `${chalk.bold.yellow('🔀 [DECISION CROSSROADS] • A path diverges •')}\n`;
755:               break;
756:             case 'Embodied':
757:               modHeader = `${chalk.bold.green('💓 [SOMATIC SCAN] • Focus on body sensation •')}\n`;
758:               break;
759:             case 'Strategic':
760:               modHeader = `${chalk.bold.magenta('♟️ [TACTICAL WAR-TABLE] • Assess constraints •')}\n`;
761:               break;
762:             case 'SocialCooperative':
763:               modHeader = `${chalk.bold.cyan('🤝 [DIPLOMACY] • Navigating connection •')}\n`;
764:               break;
765:             case 'ImmersiveRPG':
766:               modHeader = `${chalk.bold.yellow('📖 [NARRATIVE SCENE] • The story unfolds •')}\n`;
767:               break;
768:             default:
769:               modHeader = `${chalk.bold.dim('[' + (mod as string).toUpperCase() + ']')}\n`;
770:           }
771: 
772:           console.log(`\n  ${modHeader}  ${chalk.magenta('[' + q.header + ']')}`);
773:           console.log(`  ${chalk.bold(q.question)}`);
774:           if (q.options?.length) {
775:             for (let i = 0; i < q.options.length; i++) {
776:               const opt = q.options[i];
777:               console.log(`    ${chalk.cyan('[' + (i + 1) + ']')} ${opt.label} — ${opt.description}`);
778:             }
779:           }
780:         }
781: 
782:         emitEvent('ask_user', {
783:           header: q.header,
784:           question: q.question,
785:           options: q.options?.map((o, i) => ({ index: i + 1, label: o.label, description: o.description })),
786:           allowWriteIn: q.allowWriteIn,
787:         });
788: 
789:         if (HEADLESS) {
790:           // Use forced responses pool if provided (one index per question, consumed sequentially)
791:           let selectedIdx: number;
792:           if (responsesPool && responsesPool.length > 0) {
793:             const forcedIdx = responsesPool.shift()!;
794:             if (q.options && forcedIdx >= 1 && forcedIdx <= q.options.length) {
795:               selectedIdx = forcedIdx - 1;
796:             } else {
797:               selectedIdx = 0;
798:             }
799:           } else {
800:             // Vary selection to probe different shadow patterns:
801:             // Cycle through options to ensure shadow detection has varied input
802:             const hash = (Date.now() + (q.options?.length ?? 4)) % 4;
803:             selectedIdx = hash < (q.options?.length ?? 4) ? hash : 0;
804:           }
805:           const selectedOpt = q.options?.[selectedIdx];
806:           const selectedLabel = selectedOpt?.label ?? '';
807: 
808:           // Shadow keyword injection for testing — randomly inject (10% chance)
809:           // to allow MOST encounters to pass and demonstrate altitude shifts.
810:           // When FORCE_SHADOW=none, skip injection entirely for clean progression.
811:           const shadowInjections = ['', 'i feel the need to withdraw from this confrontation', 'i must transcend these petty concerns and reach enlightenment', 'i prefer to stay here where it is safe and comfortable'];
812:           const injectShadow = FORCE_SHADOW !== 'none' && selectedIdx > 0 && Math.random() < 0.1;
813:           const writeInShadow = injectShadow ? (shadowInjections[selectedIdx] ?? '') : '';
814: 
815:           if (writeInShadow) {
816:             answers.push({ selectedLabels: [selectedLabel], writeInValue: writeInShadow });
817:           } else {
818:             answers.push({ selectedLabels: [selectedLabel] });
819:           }
820:         } else {
821:           const promptText = q.multiSelect
822:             ? '\n  Select (comma-separated): '
823:             : '\n  Select: ';
824:           const answer = await ask(promptText);
825:           const selections = answer.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
826:           const selectedLabels = selections
827:             .filter(n => n >= 1 && n <= (q.options?.length ?? 0))
828:             .map(n => q.options![n - 1]!.label);
829: 
830:           // Determine if input is a simple numeric choice from the options
831:           let isSimpleNumericChoice = false;
832:           if (q.options?.length && answer.trim()) {
833:             const parts = answer.split(',').map(s => s.trim());
834:             isSimpleNumericChoice = parts.every(part => {
835:               const num = parseInt(part, 10);
836:               return !isNaN(num) && String(num) === part && num >= 1 && num <= q.options!.length;
837:             });
838:           }
839: 
840:           if (q.allowWriteIn || (!q.options?.length && answer.trim())) {
841:             // Only populate writeInValue if it's NOT a simple numeric choice
842:             if (!isSimpleNumericChoice && answer.trim()) {
843:               answers.push({ selectedLabels, writeInValue: answer.trim() });
844:             } else {
845:               answers.push({ selectedLabels });
846:             }
847:           } else {
848:             answers.push({ selectedLabels });
849:           }
850:         }
851:       }
852: 
853:       return { answers };
854:     }
855:   };
856: 
857:   // Always route through AgenticOrchestrator — it handles LLM + fallback internally
858:   // Look up the assessment module from the registry to inject into the LLM context
859:   const baseModule = modRegistry?.get(encLine, encStage);
860: 
861:   // Build ConceptDraftIndex from the module registry so the LLM sees module metadata
862:   const conceptModules: Record<string, any> = {};
863:   if (modRegistry) {
864:     for (const m of modRegistry.getAll()) {
865:       const key = `${m.line.toLowerCase()}:${m.stage.toLowerCase()}`;
866:       conceptModules[key] = {
867:         line: m.line,
868:         stage: m.stage,
869:         title: `${m.line} ${m.stage} Module`,
870:         modalities: m.tasks.map(t => t.type === 'llm_dialogue' ? 'LanguageReflective' as const : 'Deterministic' as const),
871:       };
872:     }
873:   }
874: 
875:   const orchestrator = new AgenticOrchestrator({
876:     encounter: forcedEncounter,
877:     significator: sig,
878:     world,
879:     history,
880:     conceptIndex: { modules: conceptModules },
881:     uiHandler,
882:     module: modRegistry?.get(FORCE_LINE ?? encLine, FORCE_STAGE ?? encStage) ?? baseModule,
883:     noLlm: !LLM_ACTIVE,
884:     forceShadow: FORCE_SHADOW,
885:     consecutivePasses,
886:   });
887: 
888:   const outcome = await orchestrator.run();
889: 
890:   // Build a PlayerResponse from the orchestrator's consequence record
891:   const cr = outcome.consequenceRecord;
892:   const response: PlayerResponse = {
893:     encounterId: encounter.id,
894:     energeticDirection: cr.polarityTrace.energeticDirection,
895:     driveDirectionality: cr.polarityTrace.driveDirectionality,
896:     stageOrientation: cr.polarityTrace.stageOrientation,
897:     sourceOfNourishment: cr.polarityTrace.sourceOfNourishment,
898:     shadowSurfaced: cr.shadowSurfaced,
899:     shadowResolvedId: cr.shadowResolved,
900:     narrativeSummary: outcome.narrativeSummary,
901:   };
902: 
903:   return { outcome, response, narrativeSummary: outcome.narrativeSummary };
904: }
