274:   private buildBriefHistory(): string {
275:     if (this.history.length === 0) return '';
276:     const last3 = this.history.slice(-3);
277:     const parts: string[] = [`You have faced ${this.history.length} challenges before.`];
278:     for (const r of last3) {
279:       const passed = Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced');
280:       const shadow = r.shadowSurfaced ? ` A ${r.shadowSurfaced} pattern surfaced.` : '';
281:       parts.push(passed
282:         ? `Recently: ${r.narrativeSummary.slice(0, 100)}...${shadow}`
283:         : `Recently: ${r.narrativeSummary.slice(0, 100)}...${shadow}`);
284:     }
285:     return parts.join(' ') + ' Now: ';
286:   }
