288:   public async run(): Promise<OrchestratorResult> {
289:     const [line, stage] = this.encounter.moduleRef.split(':') as [Line, Stage];
290:     const now = Date.now();
291: 
292:     // 1. Build context system prompt
293:     const continuityContext = this.buildContinuityContext();
294:     const contextInput = {
295:       encounter: this.encounter,
296:       significator: this.significator,
297:       holonRegistry: { holons: this.world.holons },
298:       conceptIndex: this.conceptIndex,
299:       recentConsequences: this.history,
300:       sessionContext: { energy: 'high' as const },
301:     };
302:     const context = buildContext(contextInput);
303: 
304:     // Build assessment module context for the LLM
305:     const assessmentContext = this.module ? this.buildAssessmentContext(this.module) : '';
306: 
307:     const systemPrompt = `${context.systemPrompt}${assessmentContext}${continuityContext}
308: [AGENT RULES]
309: 1. You are the Agentic Game Master driving this developmental encounter.
310: 2. Present the encounter situationally and narratively. If you need to present stimuli, choices, or ask questions, ALWAYS call the 'ask_user_question' tool. Do not ask questions in raw text responses.
311: 3. Keep the flow interactive, building upon prior answers.
312: 4. This encounter has a budget of 2 exchanges. After the player has responded to 2 questions, you MUST call 'complete_encounter'. Do NOT generate more than 2 ask_user_question calls.
313: 5. When calling 'complete_encounter', evaluate the player per the DRIVE PROBES section. Score each drive independently. Provide driveScores (0.0-1.0 per drive) and driveSignals (pathology enum per drive).
314: 6. If RECENT ENCOUNTERS are listed, reference them subtly — the player's journey has continuity.`;
315: 
316:     // If noLlm flag is set, skip LLM entirely and go directly to fallback
317:     if (this.noLlm) {
318:       return this.runFallback(line, stage, now);
319:     }
320: 
321:     if (this.messages.length === 0) {
322:       this.messages.push({
323:         role: 'user',
324:         content: `Start the encounter: ${this.encounter.id} (${line} - ${stage}). Introduce the scene and ask the first question.`
325:       });
326:     }
327: 
328:     let loopCount = 0;
329:     const maxLoops = 10; // Safety guard
330:     let askCount = 0; // Track ask_user_question calls for budget enforcement
331: 
332:     while (loopCount < maxLoops) {
333:       loopCount++;
334: 
335:       // Request next turn from LLM
336:       const res = await queryLLMWithTools(systemPrompt, this.messages, TOOLS);
337: 
338:       // Detect LLM unavailability on first call — switch to fallback
339:       if (loopCount === 1 && res.content && res.content.trim().startsWith('{"error"') && (!res.toolCalls || res.toolCalls.length === 0)) {
340:         return this.runFallback(line, stage, now);
341:       }
342: 
343:       const assistantMsg: AgentMessage = {
344:         role: 'assistant',
345:         content: res.content,
346:         toolCalls: res.toolCalls,
347:       };
348:       this.messages.push(assistantMsg);
349: 
350:       if (res.toolCalls && res.toolCalls.length > 0) {
351:         // Execute tool calls
352:         for (const tc of res.toolCalls) {
353:           if (tc.function.name === 'ask_user_question') {
354:             askCount++;
355:             const params = JSON.parse(tc.function.arguments) as AskUserQuestionParams;
356:             
357:             // Present to UI (Phaser or CLI)
358:             const result = await this.uiHandler.askUser(params);
359: 
360:             // Record tool response
361:             this.messages.push({
362:               role: 'tool',
363:               content: JSON.stringify(result),
364:               toolCallId: tc.id,
365:               name: 'ask_user_question'
366:             });
367: 
368:             // Budget enforcement: after 2 exchanges, force complete_encounter
369:             if (askCount >= 2 && !res.toolCalls.some(t => t.function.name === 'complete_encounter')) {
370:               this.messages.push({
371:                 role: 'user',
372:                 content: 'The encounter budget of 2 exchanges is exhausted. You MUST now call complete_encounter with your evaluation of the player. Do NOT ask another question.'
373:               });
374:             }
375:           } else if (tc.function.name === 'complete_encounter') {
376:             const params = JSON.parse(tc.function.arguments) as {
377:               passed: boolean;
378:               scores?: Partial<Record<MeasureDimension, number>>;
379:               driveScores: { agency: number; communion: number; eros: number; agape: number };
380:               driveSignals: { agency: string; communion: string; eros: string; agape: string };
381:               feedback: string;
382:               polarityDirection: 'sto' | 'sts' | 'neutral';
383:               shadowSignal?: {
384:                 quadrant: ShadowQuadrant;
385:                 intensity: number;
386:               };
387:               narrativeSummary: string;
388:             };
389: 
390:             // Process completion with per-drive scores
391:             const finalResult = this.createAssessmentResult(params.passed, params.scores || {}, params.driveScores);
392:             const outcome = this.finalizeEncounter(params, now);
393: 
394:             return {
395:               ...outcome,
396:               finalResult,
397:               messages: this.messages,
398:             };
399:           }
400:         }
401:       } else {
402:         // Fallback: If assistant didn't call any tools, prompt it to proceed
403:         this.messages.push({
404:           role: 'user',
405:           content: 'Continue with the encounter. If the encounter is complete, call complete_encounter. Otherwise, call ask_user_question.'
406:         });
407:       }
408:     }
409: 
410:     // Safety fallback termination if we loop too many times
411:     const fallbackParams = {
412:       passed: true,
413:       feedback: 'Encounter completed via timeout.',
414:       polarityDirection: 'neutral' as const,
415:       narrativeSummary: `The player successfully navigated the challenge of ${this.encounter.moduleRef}.`,
416:     };
417:     const finalResult = this.createAssessmentResult(true, {});
418:     const outcome = this.finalizeEncounter(fallbackParams, now);
419: 
420:     return {
421:       ...outcome,
422:       finalResult,
423:       messages: this.messages,
424:     };
425:   }
