558:   /**
559:    * Module-aware fallback: uses the assessment module's tasks, drive probes,
560:    * and scoring rubric to present a real developmental assessment even without the LLM.
561:    * Selects a task matching the encounter modality, presents it as a narrative challenge,
562:    * evaluates the response against drive probes, detects shadow patterns,
563:    * and computes altitude progression.
564:    */
565:   private async runModuleAssessment(_line: Line, stage: Stage, now: number): Promise<OrchestratorResult> {
566:     const module = this.module!;
567:     const holon = this.world.holons.find(h => h.id === this.encounter.holonSource);
568:     const holonName = holon?.name ?? 'A presence';
569:     const currentModality = this.encounter.modality;
570: 
571:     // 1. Select the best task from the module based on modality
572:     const task = this.selectTaskForModality(module, currentModality);
573:     // Track the actual presented task for narrative building (fix B.2)
574:     this._currentPresentedTask = task;
575: 
576:     // 2. Present the task as a narrative challenge via uiHandler
577:     const askResult = await this.presentModuleTask(module, task, currentModality, holonName);
578:     const answer = askResult.answers[0];
579:     const rawLabel = answer?.selectedLabels[0] ?? '';
580:     const writeIn = answer?.writeInValue;
581:     const playerResponseText = writeIn ?? rawLabel;
582: 
583:     // 3. Evaluate using the TaskRenderer's evaluate() if available (produces TrialResult with timing/accuracy)
584:     //    Fall back to drive-probe evaluation if no renderer evaluate is available
585:     const endTimeMs = Date.now();
586:     let evaluation: {
587:       passed: boolean;
588:       polarityDirection: 'sto' | 'sts' | 'neutral';
589:       driveScores: { agency: number; communion: number; eros: number; agape: number };
590:       driveSignals: { agency: string; communion: string; eros: string; agape: string };
591:       feedback: string;
592:     };
593:     let trialResult: TrialResult | null = null;
594: 
595:     if (this._currentRendererEvaluate) {
596:       // Use the TaskRenderer's evaluate function for real scoring
597:       trialResult = this._currentRendererEvaluate(playerResponseText, this._currentTaskStartTime, endTimeMs);
598: 
599:       // Extract drive metadata from the trial's rawResponse (set by TaskRenderers)
600:       const rawResp = trialResult?.rawResponse as any;
601:       const matchedDrive: string | null = rawResp?.matchedDrive ?? null;
602:       const matchedPolarity: string = rawResp?.matchedPolarity ?? 'neutral';
603:       const correctnessScore: number = rawResp?.correctnessScore ?? 0.5;
604: 
605:       // Use correctnessScore as the primary scoring signal (from TaskRenderer options)
606:       const baseScore = Math.min(1, Math.max(0, correctnessScore));
607: 
608:       // D.9: Use shared shadow keyword detection helper (DRY)
609:       let writeInDriveDetection: { drive: string; polarity: string; shadowKeyword: string | null } | null = null;
610:       if (writeIn) {
611:         writeInDriveDetection = AgenticOrchestrator.detectWriteInShadow(writeIn);
612:       }
613: 
614:       // When a write-in is present, its keyword-based detection takes priority over
615:       // the renderer's label matching (which can false-positive on short words like 'I').
616:       const effectiveDrive = writeInDriveDetection?.drive ?? matchedDrive ?? null;
617:       const effectivePolarity = writeInDriveDetection?.polarity ?? (matchedPolarity !== 'neutral' ? matchedPolarity : 'neutral');
618: 
619:       // Build differentiated drive scores:
620:       // - The matched/driven drive gets the full baseScore (or boosted for write-in depth)
621:       // - Other drives get baseline neutral (0.5)
622:       // - For write-ins with no shadow detection, apply a depth boost and distribute evenly
623:       const isWriteInWithNoShadow = matchedDrive === null && !writeInDriveDetection && !!writeIn;
624: 
625:       // ── SCORING FIX: Use rubric dimension weights on TrialResult dimensions ──
626:       // OLD: averaged 4 drives → compressed to ~0.55 always, even correct answers failed at threshold 0.6
627:       // NEW: compute weighted score from TrialResult dimensions using the module's rubric weights.
628:       // This gives a true performance signal: correct MCQ → ~0.8, partial → ~0.55, wrong → ~0.25.
629:       const rubricWeights = module.scoringRubric.dimensionWeights;
630:       const trialDims = trialResult!.dimensions;
631:       let weightedSum = 0;
632:       let totalWeight = 0;
633:       for (const [dim, weight] of Object.entries(rubricWeights)) {
634:         const val = trialDims[dim as keyof typeof trialDims];
635:         if (weight && typeof val === 'number') {
636:           weightedSum += val * weight;
637:           totalWeight += weight;
638:         }
639:       }
640:       // Blend the rubric-weighted score with the drive-correctness score for a robust signal
641:       const rubricScore = totalWeight > 0 ? weightedSum / totalWeight : baseScore;
642:       const blendedScore = rubricScore * 0.6 + baseScore * 0.4;
643: 
644:       // Drive scores: matched drive gets blendedScore (consistent with pass/fail),
645:       // write-in depth bonus applied on top. Unmatched drives get a lower baseline.
646:       const matchedScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
647:       const driveScores = {
648:         agency: effectiveDrive === 'agency' ? matchedScore
649:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
650:           : matchedScore,
651:         communion: effectiveDrive === 'communion' ? matchedScore
652:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
653:           : matchedScore,
654:         eros: effectiveDrive === 'eros' ? matchedScore
655:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
656:           : matchedScore,
657:         agape: effectiveDrive === 'agape' ? matchedScore
658:           : effectiveDrive !== null ? Math.min(0.5, blendedScore * 0.7)
659:           : matchedScore,
660:       };
661: 
662:       // Determine polarity from the effective drive detection
663:       const polarityDirection = effectivePolarity === 'sts' ? 'sts' as const
664:         : effectivePolarity === 'sto' ? 'sto' as const
665:         : 'neutral' as const;
666: 
667:       // Derive drive signals from the expression pattern.
668:       // IMPORTANT: Shadow signals ONLY come from write-in keyword detection or forceShadow.
669:       // A wrong MCQ answer (low correctnessScore) is a performance miss, NOT a shadow expression.
670:       const shadowFromWriteIn = writeInDriveDetection?.shadowKeyword ?? null;
671:       const driveSignals = {
672:         agency: effectiveDrive === 'agency'
673:           ? (shadowFromWriteIn === 'DarkAddicted' ? 'DarkAddicted' : 'HealthyBalanced')
674:           : 'HealthyBalanced',
675:         communion: effectiveDrive === 'communion'
676:           ? (shadowFromWriteIn === 'DarkAverted' ? 'DarkAverted' : 'HealthyBalanced')
677:           : 'HealthyBalanced',
678:         eros: effectiveDrive === 'eros'
679:           ? (shadowFromWriteIn === 'GoldenAddicted' ? 'GoldenAddicted' : 'HealthyBalanced')
680:           : 'HealthyBalanced',
681:         agape: effectiveDrive === 'agape'
682:           ? (shadowFromWriteIn === 'GoldenAverted' ? 'GoldenAverted' : 'HealthyBalanced')
683:           : 'HealthyBalanced',
684:       };
685: 
686:       // Determine pass: blendedScore must meet threshold AND no shadow pathology
687:       const passThreshold = module.scoringRubric.passThreshold ?? 0.5;
688:       const effectiveScore = isWriteInWithNoShadow ? Math.max(blendedScore, 0.55) : blendedScore;
689:       const hasShadow = !!shadowFromWriteIn;
690:       const passed = !hasShadow && effectiveScore >= passThreshold;
691: 
692:       // Build contextual developmental feedback based on score, drive, polarity, and history
693:       const driveLabel = effectiveDrive ?? 'unidentified';
694:       const polarityLabel = effectivePolarity === 'sts' ? 'self-oriented' : effectivePolarity === 'sto' ? 'other-oriented' : 'balanced';
695:       const scorePct = (baseScore * 100).toFixed(0);
696:       const historyCount = this.history.length;
697:       const recentPasses = this.history.slice(-3).filter(r => Object.values(r.polarityTrace.driveDirectionality).every(d => d === 'HealthyBalanced')).length;
698:       const consistencyNote = recentPasses >= 3 ? ' You are building strong momentum across encounters.'
699:         : recentPasses === 0 && historyCount >= 2 ? ' The last few encounters have been challenging — this is where real growth happens.'
700:         : '';
701: 
702:       const feedback = hasShadow
703:         ? `A ${shadowFromWriteIn} pattern surfaced through your ${driveLabel} expression (${polarityLabel}). In the developmental framework, this shadow arises when the ${driveLabel} drive becomes imbalanced — either clinging to lower patterns (dark) or bypassing toward higher without integration (golden). Naming it here is the first step toward healing it. ${historyCount > 0 ? `This is your ${historyCount + 1}th encounter — each shadow surfaced is an opportunity for the field to work with you.` : ''}`
704:         : passed
705:           ? `Your ${driveLabel} drive expressed with health (performance: ${scorePct}%, polarity: ${polarityLabel}). ${parseInt(scorePct) >= 80 ? 'Strong performance — the integration is deepening across the ' + module.line.toLowerCase() + ' dimension.' : 'Solid engagement — the ' + module.line.toLowerCase() + ' capacity at ' + module.stage + ' stage is growing.'} ${consistencyNote}The field recognizes your sustained attention to this developmental edge.`
706:           : `Your ${driveLabel} drive expressed at ${scorePct}% performance (${polarityLabel}). ${parseInt(scorePct) >= 40 ? 'Close to the threshold — the gap between where you are and where this capacity can be is narrowing. A focused effort on the next encounter may tip the balance.' : 'This is a genuine edge for you. The ' + module.line.toLowerCase() + ' line at ' + module.stage + ' stage is where your developmental work lives right now — not as punishment, but as invitation.'} The ${module.line.toLowerCase()} dimension will continue to offer opportunities to strengthen this capacity.`;
707: 
708:       evaluation = {
709:         passed,
710:         polarityDirection,
711:         driveScores,
712:         driveSignals,
713:         feedback,
714:       };
715:     } else {
716:       // Fallback: keyword-based evaluation
717:       evaluation = this.evaluateViaDriveProbes(module, playerResponseText);
718:     }
719: 
720:     // 4. Detect shadow surfacing from response pattern (with optional forceShadow override)
721:     const validQuadrants = ['DarkAddiction', 'DarkAllergy', 'GoldenAddiction', 'GoldenAllergy'] as const;
722:     const forcedQuadrant = this.forceShadow && validQuadrants.includes(this.forceShadow as any)
723:       ? this.forceShadow as ShadowQuadrant
724:       : null;
725:     // Shadow detection only fires for write-in text (free-form responses)
726:     // MCQ option labels should NOT trigger shadow detection — they're structured choices, not expressions.
727:     const isWriteIn = !!writeIn;
728:     const shadowSignal = forcedQuadrant
729:       ? { quadrant: forcedQuadrant, intensity: 0.7 }
730:       : this.detectShadowFromResponse(playerResponseText, currentModality, isWriteIn);
731: 
732:     // If forceShadow is active, propagate to drive signals AND force-fail the encounter
733:     if (forcedQuadrant && this._currentRendererEvaluate) {
734:       const forcedDrive = forcedQuadrant === 'DarkAddiction' ? 'agency'
735:         : forcedQuadrant === 'DarkAllergy' ? 'communion'
736:         : forcedQuadrant === 'GoldenAddiction' ? 'eros'
737:         : 'agape';
738:       const forcedSignal = forcedQuadrant;
739:       evaluation.driveSignals = { ...evaluation.driveSignals, [forcedDrive]: forcedSignal } as typeof evaluation.driveSignals;
740:       // Forced shadow = pathology detected → must fail
741:       evaluation = { ...evaluation, passed: false, feedback: `Shadow surfaced: ${forcedQuadrant} through ${forcedDrive} expression (forced). This indicates the ${forcedDrive} drive is operating from a developmental shadow — awareness of this pattern is the first step toward integration.` };
742:     }
743: 
744:     // 5. Build a rich narrative summary from the module context
745:     // Pass the actual presented task so narrative matches what the user saw
746:     const narrativeSummary = this.buildModuleNarrative(module, playerResponseText, evaluation.passed, currentModality, holonName, task);
747: 
748:     // 6. Check for altitude shift: only when ALL drives HealthyBalanced AND passed
749:     const altitudeShift = this.computeAltitudeShift(evaluation.driveSignals, module, stage, evaluation.passed);
750: 
751:     const finalResult = this.createAssessmentResult(
752:       evaluation.passed, {}, evaluation.driveScores, trialResult ? [trialResult] : undefined,
753:     );
754: 
755:     // Build outcome with altitude shift support
756:     const energeticDirection: EnergeticDirection = evaluation.polarityDirection === 'sto' ? 'Radiative'
757:       : evaluation.polarityDirection === 'sts' ? 'Absorptive' : 'Diffuse';
758: 
759:     const SIGNAL_MAP: Record<string, DriveDirectionality> = {
760:       'HealthyBalanced': 'HealthyBalanced',
761:       'DarkAddicted': 'DarkAddicted',
762:       'DarkAverted': 'DarkAverted',
763:       'GoldenAddicted': 'GoldenAddicted',
764:       'GoldenAverted': 'GoldenAverted',
765:     };
766: 
767:     const baseDir: DriveDirectionality = evaluation.passed ? 'HealthyBalanced' : 'DarkAddicted';
768:     const driveDirectionality: Record<Drive, DriveDirectionality> = {
769:       Agency: SIGNAL_MAP[evaluation.driveSignals.agency] ?? baseDir,
770:       Communion: SIGNAL_MAP[evaluation.driveSignals.communion] ?? baseDir,
771:       Eros: SIGNAL_MAP[evaluation.driveSignals.eros] ?? baseDir,
772:       Agape: SIGNAL_MAP[evaluation.driveSignals.agape] ?? baseDir,
773:     };
774: 
775:     const response: PlayerResponse = {
776:       encounterId: this.encounter.id,
777:       energeticDirection,
778:       driveDirectionality: driveDirectionality as Record<Drive, DriveDirectionality>,
779:       stageOrientation: evaluation.polarityDirection === 'sto' ? 'ReachingHigher' : 'Homeostatic',
780:       sourceOfNourishment: evaluation.polarityDirection === 'sto' ? 'HigherRealm'
781:         : (evaluation.polarityDirection === 'sts' ? 'LowerRealm' : 'Ambivalent'),
782:       shadowSurfaced: shadowSignal?.quadrant ?? null,
783:       shadowResolvedId: null,
784:       narrativeSummary,
785:     };
786: 
787:     const record = processOutcome(this.encounter, response, now);
788: 
789:     // Override altitudeShift on the record if computed
790:     const updatedRecord: ConsequenceRecord = {
791:       ...record,
792:       altitudeShift: altitudeShift ?? null,
793:     };
794: 
795:     // Apply failure consequences: accelerate theta-decay for failed modules
796:     if (!evaluation.passed) {
797:       const [fl, fs] = this.encounter.moduleRef.split(':');
798:       const cellKey = `${fl}:${fs}`;
799:       const currentTs = this.significator.theta.lastEncounter[cellKey] ?? 0;
800:       if (currentTs > now - 3600000) {
801:         (this.significator.theta.lastEncounter as Record<string, number>)[cellKey] = now - 7200000;
802:       }
803:     }
804: 
805:     // Apply consequences — shadow entries will be created if shadowSurfaced is set
806:     const updated = applyConsequences(this.significator, this.world, updatedRecord, this.encounter);
807: 
808:     // Apply altitude shift if computed
809:     let finalSig = updated.sig;
810:     if (altitudeShift) {
811:       const currentOrd = stageOrdinal(altitudeShift.to);
812:       const ALL_STAGES: readonly Stage[] = ['Infrared', 'Magenta', 'Red', 'Amber', 'Orange', 'Green', 'Turquoise', 'White'];
813:       if (currentOrd < ALL_STAGES.length - 1) {
814:         const nextStage = ALL_STAGES[currentOrd + 1]!;
815:         finalSig = {
816:           ...finalSig,
817:           altitudes: { ...finalSig.altitudes, [altitudeShift.line]: nextStage },
818:         };
819:         // Update currentStage if all lines are at least at nextStage
820:         const allAtNext = Object.values(finalSig.altitudes).every(
821:           a => stageOrdinal(a) >= stageOrdinal(nextStage),
822:         );
823:         if (allAtNext) {
824:           finalSig = { ...finalSig, currentStage: nextStage };
825:         }
826:       }
827:     }
828: 
829:     // PESTLE accumulation
830:     const PESTLE_DIMS_ARRAY: (keyof PESTLETension)[] = ['political', 'economic', 'social', 'technological', 'legal', 'environmental'];
831:     const dim = PESTLE_DIMS_ARRAY[Math.floor(Math.random() * PESTLE_DIMS_ARRAY.length)]!;
832:     const newTension = accumulateTension(
833:       (updated.world as any).pestleTension ?? { political: 0, economic: 0, social: 0, technological: 0, legal: 0, environmental: 0 },
834:       dim,
835:       0.05,
836:     );
837:     const activeEvents = (updated.world as any).activeMacroEvents ?? [];
838:     const macroEvent = tryTriggerMacroEvent(newTension, activeEvents, finalSig.currentStage, now);
839:     const newActiveEvents = macroEvent ? [...activeEvents, macroEvent] : activeEvents;
840:     const updatedWorld = { ...updated.world, pestleTension: newTension, activeMacroEvents: newActiveEvents } as WorldState;
841: 
842:     return {
843:       updatedSig: finalSig,
844:       updatedWorld,
845:       finalResult,
846:       consequenceRecord: updatedRecord,
847:       narrativeSummary,
848:       feedback: evaluation.feedback,
849:       messages: this.messages,
850:     };
851:   }
