77:   Magenta: { nBackN: 1, nBackTrials: 8, stroopTrials: 6, goNoGoTrials: 10, holdItems: 2, holdDurationMs: 4000, patternDisks: 2, patternAttempts: 3, symbolPool: NBACK_SYMBOLS.slice(0, 5), stroopColors: STROOP_COLORS.slice(0, 3), goStimuli: GONOGO_STIMULI.slice(0, 3) },
