81:   Green: { nBackN: 3, nBackTrials: 16, stroopTrials: 12, goNoGoTrials: 20, holdItems: 4, holdDurationMs: 8000, patternDisks: 4, patternAttempts: 5, symbolPool: NBACK_SYMBOLS_EXTENDED, stroopColors: STROOP_COLORS_EXTENDED, goStimuli: GONOGO_STIMULI_EXTENDED },
