208: // ── Stroop Renderer ───────────────────────────────────────────────────
209: 
210: /**
211:  * Render a Stroop task: show a word printed in a different ink color,
212:  * ask the player to name the INK color (not the word).
213:  */
214: export function renderStroop(task: AssessmentTask): {
215:   prompt: AskUserQuestionParams;
216:   evaluate: (answer: string, startTimeMs: number, endTimeMs: number) => TrialResult;
217: } {
218:   const diff = getDifficulty(task.parameters.stage as string | undefined);
219:   const trialCount = (task.parameters.trials as number) ?? diff.stroopTrials;
220:   const colors = diff.stroopColors;
221: 
222:   const trials: { wordIdx: number; inkIdx: number }[] = [];
223:   for (let i = 0; i < trialCount; i++) {
224:     let wordIdx = Math.floor(Math.random() * colors.length);
225:     let inkIdx = Math.floor(Math.random() * colors.length);
226:     while (inkIdx === wordIdx) {
227:       inkIdx = Math.floor(Math.random() * colors.length);
228:     }
229:     trials.push({ wordIdx, inkIdx });
230:   }
231: 
232:   const trialDisplay = trials.map((t, i) => {
233:     const inkColor = colors[t.inkIdx]!;
234:     return `${C.dim}#${i + 1}${C.reset} ${inkColor.render}`;
235:   }).join('   ');
236: 
237:   // Generate the correct sequence
238:   const correctSequence = trials.map(t => colors[t.inkIdx]!.initial).join(',');
239: 
240:   const question = [
241:     `Name the INK COLOR of each word (not the word itself).`,
242:     ``,
243:     `${trialDisplay}`,
244:     ``,
245:     `${C.bold}What is the correct ink color sequence?${C.reset}`,
246:   ].join('\n');
247: 
248:   // Build correct and incorrect options, then shuffle
249:   const incorrectSequences = [
250:     trials.map(t => colors[(t.inkIdx + 1) % colors.length]!.initial).join(','),
251:     trials.map(t => colors[(t.inkIdx + 2) % colors.length]!.initial).join(','),
252:     trials.map(t => colors[t.wordIdx]!.initial).join(','), // Word-color (Stroop error)
253:   ];
254: 
255:   const options: DriveOption[] = [
256:     { label: correctSequence, description: 'Correct sequence', drive: 'agency', polarity: 'neutral', correctnessScore: 1.0 },
257:     { label: incorrectSequences[0]!, description: 'Partial match', drive: 'communion', polarity: 'neutral', correctnessScore: 0.5 },
258:     { label: incorrectSequences[1]!, description: 'Different sequence', drive: 'eros', polarity: 'neutral', correctnessScore: 0.3 },
259:     { label: incorrectSequences[2]!, description: 'Word-based (common error)', drive: 'agape', polarity: 'neutral', correctnessScore: 0.0 },
260:   ];
261:   shuffle(options);
262: 
263:   return {
264:     prompt: {
265:       questions: [{
266:         question,
267:         header: 'Inhibitory Control',
268:         options: options.map(o => ({ label: o.label, description: o.description })),
269:         allowWriteIn: true,
270:         multiSelect: false,
271:       }],
272:     },
273:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
274:       const durationMs = endTimeMs - startTimeMs;
275:       const colorMap: Record<string, number> = { r: 0, red: 0, b: 1, blue: 1, g: 2, green: 2, y: 3, yellow: 3 };
276:       const parts = answer.toLowerCase().split(/[, ]+/).filter(Boolean);
277:       const playerColors = parts.map(p => colorMap[p] ?? -1).filter(c => c >= 0);
278: 
279:       const expected = trials.map(t => t.inkIdx);
280:       let correct = 0;
281:       for (let i = 0; i < Math.min(playerColors.length, expected.length); i++) {
282:         if (playerColors[i] === expected[i]) correct++;
283:       }
284: 
285:       const accuracy = expected.length > 0 ? correct / expected.length : 0;
286:       const expectedTime = trialCount * 2500;
287:       const timeRatio = durationMs / expectedTime;
288:       const responseTime = timeRatio < 0.5 ? 0.9 : timeRatio < 1.5 ? 0.7 : timeRatio < 3 ? 0.5 : 0.3;
289: 
290:       const matchedOpt = options.find(o => answer.toUpperCase().includes(o.label));
291: 
292:       return {
293:         taskId: task.id,
294:         timestamp: startTimeMs,
295:         dimensions: { accuracy, response_time: responseTime, consistency: accuracy },
296:         rawResponse: {
297:           playerColors, expected, correct, total: expected.length,
298:           matchedDrive: matchedOpt?.drive ?? null,
299:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
300:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
301:         },
302:         durationMs,
303:       };
304:     },
305:   };
306: }
