397: /**
398:  * Render a Hold task: show items to remember, then ask the player to recall.
399:  */
400: export function renderHold(task: AssessmentTask): {
401:   prompt: AskUserQuestionParams;
402:   evaluate: (answer: string, startTimeMs: number, endTimeMs: number) => TrialResult;
403: } {
404:   const diff = getDifficulty(task.parameters.stage as string | undefined);
405:   const itemCount = (task.parameters.items as number) ?? diff.holdItems;
406:   const holdDurationMs = (task.parameters.holdDurationMs as number) ?? diff.holdDurationMs;
407: 
408:   const items = diff.symbolPool.slice(0, itemCount);
409: 
410:   const question = [
411:     `Remember these ${itemCount} symbols:`,
412:     ``,
413:     `  ${items.join('   ')}`,
414:     ``,
415:     `Hold them in your mind for ${Math.round(holdDurationMs / 1000)} seconds.`,
416:     `Now: ${C.bold}List the symbols in order${C.reset}`,
417:   ].join('\n');
418: 
419:   // Options: correct recall, partial, vague, forgot
420:   const options: DriveOption[] = [
421:     { label: `${items.join(' ')}`, description: `I remember: ${items.join(', ')}`, drive: 'agency', polarity: 'neutral', correctnessScore: 1.0 },
422:     { label: `${items.slice(0, -1).join(' ')}…`, description: `I remember ${items.length - 1} of them`, drive: 'communion', polarity: 'neutral', correctnessScore: 0.7 },
423:     { label: `Some symbols`, description: 'I recall parts but not all', drive: 'eros', polarity: 'neutral', correctnessScore: 0.4 },
424:     { label: `Slipped away`, description: 'The symbols faded from memory', drive: 'agape', polarity: 'neutral', correctnessScore: 0.0 },
425:   ];
426:   shuffle(options);
427: 
428:   return {
429:     prompt: {
430:       questions: [{
431:         question,
432:         header: 'Attentional Hold',
433:         options: options.map(o => ({ label: o.label, description: o.description })),
434:         allowWriteIn: true,
435:         multiSelect: false,
436:       }],
437:     },
438:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
439:       const durationMs = endTimeMs - startTimeMs;
440: 
441:       const answerLower = answer.toLowerCase();
442:       const matched = items.filter(item => answerLower.includes(item));
443:       const accuracy = matched.length / items.length;
444: 
445:       const responseTime = holdDurationMs > 0 ? Math.min(1, holdDurationMs / (holdDurationMs * 2)) : 0.7;
446:       const matchedOpt = options.find(o => answer.toLowerCase().includes(o.label.toLowerCase().split(' ')[0]!));
447: 
448:       return {
449:         taskId: task.id,
450:         timestamp: startTimeMs,
451:         dimensions: { accuracy, response_time: responseTime, consistency: accuracy },
452:         rawResponse: {
453:           items, matched, answer,
454:           matchedDrive: matchedOpt?.drive ?? null,
455:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
456:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
457:         },
458:         durationMs,
459:       };
460:     },
461:   };
462: }
