464: // ── Pattern Prediction Renderer ──────────────────────────────────────
465: 
466: export function renderPatternPrediction(task: AssessmentTask): {
467:   prompt: AskUserQuestionParams;
468:   evaluate: (answer: string, startTimeMs: number, endTimeMs: number) => TrialResult;
469: } {
470:   const diff = getDifficulty(task.parameters.stage as string | undefined);
471:   const disks = (task.parameters.disks as number) ?? diff.patternDisks;
472:   const attempts = (task.parameters.attempts as number) ?? diff.patternAttempts;
473: 
474:   const base = Math.floor(Math.random() * 5) + 1;
475:   const step = Math.floor(Math.random() * 3) + 1;
476:   const pattern = Array.from({ length: 4 }, (_, i) => base + step * i);
477:   const nextValue = pattern[3]! + step;
478: 
479:   const question = [
480:     `Observe the pattern of ${disks} elements across ${attempts} steps:`,
481:     ``,
482:     `  ${pattern.map((v, i) => `${C.dim}Step ${i + 1}:${C.reset} ${'█'.repeat(v)} ${v}`).join('\n  ')}`,
483:     ``,
484:     `${C.bold}What is Step 5?${C.reset}`,
485:   ].join('\n');
486: 
487:   const options: DriveOption[] = [
488:     { label: `${nextValue}`, description: `The next value (increasing by ${step})`, drive: 'agency', polarity: 'neutral', correctnessScore: 1.0 },
489:     { label: `${nextValue + step}`, description: `Larger step`, drive: 'communion', polarity: 'neutral', correctnessScore: 0.3 },
490:     { label: `${nextValue - 1}`, description: `Close but not quite`, drive: 'eros', polarity: 'neutral', correctnessScore: 0.5 },
491:     { label: `No pattern`, description: 'I see no clear pattern', drive: 'agape', polarity: 'neutral', correctnessScore: 0.0 },
492:   ];
493:   shuffle(options);
494: 
495:   return {
496:     prompt: {
497:       questions: [{
498:         question,
499:         header: 'Pattern Recognition',
500:         options: options.map(o => ({ label: o.label, description: o.description })),
501:         allowWriteIn: true,
502:         multiSelect: false,
503:       }],
504:     },
505:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
506:       const durationMs = endTimeMs - startTimeMs;
507:       const numericMatch = answer.match(/\d+/);
508:       const playerValue = numericMatch ? parseInt(numericMatch[0]!, 10) : -1;
509: 
510:       const error = Math.abs(playerValue - nextValue);
511:       const accuracy = Math.max(0, 1 - error / Math.max(1, disks));
512: 
513:       const expectedTime = attempts * 3000;
514:       const timeRatio = durationMs / expectedTime;
515:       const responseTime = timeRatio < 0.5 ? 0.9 : timeRatio < 1.5 ? 0.7 : timeRatio < 3 ? 0.5 : 0.3;
516: 
517:       const matchedOpt = options.find(o => answer.includes(o.label));
518: 
519:       return {
520:         taskId: task.id,
521:         timestamp: startTimeMs,
522:         dimensions: {
523:           accuracy,
524:           response_time: responseTime,
525:           complexity_handled: accuracy,
526:           self_correction: error <= 1 ? 0.8 : 0.4,
527:         },
528:         rawResponse: {
529:           pattern, nextValue, playerValue, step,
530:           matchedDrive: matchedOpt?.drive ?? null,
531:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
532:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
533:         },
534:         durationMs,
535:       };
536:     },
537:   };
538: }
