540: // ── Emotion Identification Renderer ──────────────────────────────────
541: 
542: export function renderEmotionIdentification(task: AssessmentTask): {
543:   prompt: AskUserQuestionParams;
544:   evaluate: (answer: string, startTimeMs: number, endTimeMs: number) => TrialResult;
545: } {
546:   const scenarios = [
547:     { text: 'A friend shares devastating news about a loved one. You feel your chest tighten.', emotion: 'Grief', wrong: ['Anger', 'Fear', 'Joy'] },
548:     { text: 'You achieve something you worked months for. Your hands tremble slightly.', emotion: 'Pride', wrong: ['Relief', 'Exhaustion', 'Anxiety'] },
549:     { text: 'Someone betrays a trust you placed in them. Your face flushes hot.', emotion: 'Betrayal', wrong: ['Sadness', 'Confusion', 'Indifference'] },
550:     { text: 'You see a stranger being mistreated in public. Something inside you moves.', emotion: 'Moral Outrage', wrong: ['Curiosity', 'Amusement', 'Boredom'] },
551:     { text: 'You are alone in a dark forest at night. Every sound is amplified.', emotion: 'Fear', wrong: ['Excitement', 'Peace', 'Anger'] },
552:     { text: 'Someone you love tells you they need space. You feel a cold knot in your stomach.', emotion: 'Abandonment', wrong: ['Relief', 'Curiosity', 'Indifference'] },
553:     { text: 'You finally understand something that confused you for years. Your mind feels clear.', emotion: 'Clarity', wrong: ['Boredom', 'Fear', 'Anger'] },
554:   ];
555: 
556:   const scenario = scenarios[Math.floor(Math.random() * scenarios.length)]!;
557:   const correctOpt: DriveOption = { label: scenario.emotion, description: 'Identify this emotion', drive: 'eros', polarity: 'neutral', correctnessScore: 1.0 };
558:   const wrongOpts: DriveOption[] = scenario.wrong.map((w, i) => ({
559:     label: w,
560:     description: 'A different emotional state',
561:     drive: i === 0 ? 'agency' : i === 1 ? 'communion' : 'agape',
562:     polarity: 'neutral',
563:     correctnessScore: 0.2,
564:   }));
565:   const options = shuffle([correctOpt, ...wrongOpts]);
566: 
567:   const question = [
568:     `Read this scenario and identify the PRIMARY emotion:`,
569:     ``,
570:     `  "${scenario.text}"`,
571:     ``,
572:     `${C.bold}What emotion does the person feel?${C.reset}`,
573:   ].join('\n');
574: 
575:   return {
576:     prompt: {
577:       questions: [{
578:         question,
579:         header: 'Emotional Literacy',
580:         options: options.map(o => ({ label: o.label, description: o.description })),
581:         allowWriteIn: true,
582:         multiSelect: false,
583:       }],
584:     },
585:     evaluate: (answer: string, startTimeMs: number, endTimeMs: number): TrialResult => {
586:       const durationMs = endTimeMs - startTimeMs;
587:       const isCorrect = answer.toLowerCase().includes(scenario.emotion.toLowerCase());
588: 
589:       const accuracy = isCorrect ? 0.9 : 0.3;
590:       const responseTime = durationMs < 10000 ? 0.8 : durationMs < 30000 ? 0.6 : 0.4;
591: 
592:       const matchedOpt = options.find(o => answer.toLowerCase().includes(o.label.toLowerCase()));
593: 
594:       return {
595:         taskId: task.id,
596:         timestamp: startTimeMs,
597:         dimensions: {
598:           accuracy,
599:           response_time: responseTime,
600:           depth: isCorrect ? 0.7 : 0.3,
601:         },
602:         rawResponse: {
603:           scenario: scenario.text, playerEmotion: answer, expectedEmotion: scenario.emotion, isCorrect,
604:           matchedDrive: matchedOpt?.drive ?? null,
605:           matchedPolarity: matchedOpt?.polarity ?? 'neutral',
606:           correctnessScore: matchedOpt?.correctnessScore ?? 0.5,
607:         },
608:         durationMs,
609:       };
610:     },
611:   };
612: }
