1430:     const res = await fetch('http://localhost:11434/api/tags', { signal: controller.signal });
1431:     clearTimeout(timeout);
1432:     if (!res.ok) return { running: false, models: [] };
1433:     const data = (await res.json()) as { models?: { name: string }[] };
1434:     const models = (data.models ?? []).map(m => m.name.split(':')[0] ?? m.name);
1435:     return { running: true, models: [...new Set(models)] };
1436:   } catch {
1437:     return { running: false, models: [] };
1438:   }
1439: }
